rows, meta = [], []
for f, title, cat, desc, uses, tags, note in C:
    path = OUT + f + '.mp4'
    if not os.path.exists(path): print('MISSING', f); continue
    dur = float(subprocess.check_output(['ffprobe', '-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', path]))
    w, h = subprocess.check_output(['ffprobe', '-v', 'error', '-select_streams', 'v', '-show_entries', 'stream=width,height', '-of', 'csv=p=0', path]).decode().strip().split(',')
    full = desc + ' ' + note
    rows.append([f + '.mp4', title, cat, full, uses, tags])
    meta.append(dict(id=f, title=title, category=cat, description=full, uses=uses, tags=[t.strip() for t in tags.split(',')],
                     file=f + '.mp4', poster=f + '-poster.jpg', duration=round(dur, 1), width=int(w), height=int(h),
                     loop='countdown' not in f, green_screen='green-screen' in f))
with open(OUT + 'clip-listings.csv', 'w', newline='') as fh:
    wr = csv.writer(fh); wr.writerow(['file', 'title', 'category', 'description', 'suggested uses', 'tags']); wr.writerows(rows)
json.dump(meta, open(OUT + 'clips.json', 'w'), indent=1, ensure_ascii=False)
print(len(rows), 'clips listed')
